628	    /// Run a whole stream. `decide` answers each Decide at once; `None` leaves it pending.
629	    struct Run {
630	        out: String,
631	        decides: Vec<(HoldKey, Vec<ToolCall>)>,
632	        counts: Vec<Metric>,
633	    }
634	    type Decider<'a> = dyn Fn(&[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>> + 'a;
635	    fn run_format(format: Format, limits: Limits, chunks: &[String], decide: &Decider<'_>) -> (Run, Interceptor) {
636	        let t0 = Instant::now();
637	        let mut i = Interceptor::new(format, limits, Bytes::from_static(TERMINAL), t0);
638	        let mut r = Run {
639	            out: String::new(),
640	            decides: Vec::new(),
641	            counts: Vec::new(),
642	        };
643	        let mut pending: Vec<Action> = Vec::new();
644	        for c in chunks {
645	            pending.extend(i.push(c.as_bytes(), t0));
646	            drain(&mut i, &mut pending, &mut r, decide, t0);
647	        }
648	        pending.extend(i.finish(t0));
649	        drain(&mut i, &mut pending, &mut r, decide, t0);
650	        (r, i)
651	    }
652	    fn run_with(limits: Limits, chunks: &[String], decide: impl Fn(&[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>>) -> Run {
