654	    }
655	    fn drain(i: &mut Interceptor, pending: &mut Vec<Action>, r: &mut Run, decide: &Decider<'_>, now: Instant) {
656	        while !pending.is_empty() {
657	            for a in std::mem::take(pending) {
658	                match a {
659	                    Action::Emit(b) => r.out.push_str(std::str::from_utf8(&b).unwrap()),
660	                    Action::Decide { hold, calls } => {
661	                        r.decides.push((hold, calls.clone()));
662	                        if let Some(res) = decide(&calls) {
663	                            pending.extend(i.decided(hold, res, now));
664	                        }
665	                    }
666	                    Action::Count(m) => r.counts.push(m),
667	                    Action::Wake(_) => {}
668	                }
669	            }
670	        }
671	    }
672	    fn allow(c: &[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>> {
673	        Some(Ok(vec![Decision::Allow; c.len()]))
674	    }
