761	        let mut p = OpenAiStream::default();
762	        let v = Verdicts::new();
763	        assert!(p.step(rec(r#"{"object":"chat.completion.chunk","id":"c"}"#), &v).is_ok());
764	        assert!(p.step(rec(&chunk(json!([{"index":0}]))), &v).is_ok());
765	        start_call(&mut p, &v);
766	        p.step(
767	            rec(&chunk(
768	                json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":"}"}}]},"finish_reason":"tool_calls"}]),
769	            )),
770	            &v,
771	        )
772	        .ok()
773	        .unwrap();
774	        let usage = json!({"object":"chat.completion.chunk","id":"c","choices":[],"usage":{"total_tokens":1}}).to_string();
775	        assert!(p.step(rec(&usage), &v).is_ok());
776	    }
777	
778	    fn dev(r: Result<Step, StepError>) -> Option<&'static str> {
779	        match r {
780	            Err(StepError::Deviation(d)) => Some(d),
781	            _ => None,
782	        }
783	    }
784	
785	    /// Spec § 5.7: an array outside `tool_calls` inside an open call, at each place openai-python
786	    /// merges it, at any depth.
787	    #[test]
788	    fn an_array_outside_tool_calls_inside_an_open_call_deviates() {
789	        let v = Verdicts::new();
790	        for delta in [
791	            json!({"foo":[{"index":0}]}),
792	            json!({"foo":[1]}),
793	            json!({"foo":{"bar":[1]}}),
794	            json!({"refusal":[]}),
795	            json!({"tool_calls":[{"index":0,"function":{"arguments":""},"x":[{"index":0}]}]}),
796	            json!({"tool_calls":[{"index":0,"function":{"arguments":"","x":[1]}}]}),
797	            json!({"tool_calls":[{"index":0,"x":{"y":[]}}]}),
798	        ] {
799	            let mut p = OpenAiStream::default();
800	            start_call(&mut p, &v);
801	            assert_eq!(dev(p.step(rec(&chunk(json!([{"index":0,"delta":delta}]))), &v)), Some("array_outside_tool_calls"), "{delta}");
802	        }
803	        // In another choice's entry too: openai-python raises for the whole stream.
804	        let mut p = OpenAiStream::default();
805	        p.step(rec(&chunk(json!([{"index":0,"delta":{"content":""}},{"index":1,"delta":{"content":""}}]))), &v).ok().unwrap();
806	        start_call(&mut p, &v);
807	        assert_eq!(dev(p.step(rec(&chunk(json!([{"index":1,"delta":{"foo":[1]}}]))), &v)), Some("array_outside_tool_calls"));
808	    }
809	
810	    #[test]
811	    fn an_array_in_a_custom_or_legacy_body_deviates() {
812	        let v = Verdicts::new();
813	        let mut p = OpenAiStream::default();
814	        p.step(
815	            rec(&chunk(
816	                json!([{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c","type":"custom","custom":{"name":"n","input":"a"}}]}}]),
817	            )),
818	            &v,
819	        )
820	        .ok()
821	        .unwrap();
822	        let r = p.step(rec(&chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"custom":{"input":"b","x":[1]}}]}}]))), &v);
823	        assert_eq!(dev(r), Some("array_outside_tool_calls"));
824	        let mut p = OpenAiStream::default();
825	        p.step(rec(&chunk(json!([{"index":0,"delta":{"function_call":{"name":"f","arguments":"{"}}}]))), &v).ok().unwrap();
826	        let r = p.step(rec(&chunk(json!([{"index":0,"delta":{"function_call":{"arguments":"}"},"x":[1]}}]))), &v);
827	        assert_eq!(dev(r), Some("array_outside_tool_calls"));
828	    }
829	
830	    /// R-B: the record that opens a call counts (probe G1e): the raise in it cuts the call.
831	    #[test]
832	    fn an_array_in_the_record_that_opens_a_call_deviates() {
833	        let v = Verdicts::new();
834	        let mut p = OpenAiStream::default();
835	        assert!(p.step(rec(&chunk(json!([{"index":0,"delta":{"role":"assistant","content":"","foo":[{"index":0}]}}]))), &v).is_ok());
836	        let opening = json!({"tool_calls":[{"index":0,"id":"c","type":"function","function":{"name":"read","arguments":"{"}}],"foo":[1]});
837	        assert_eq!(dev(p.step(rec(&chunk(json!([{"index":0,"delta":opening}]))), &v)), Some("array_outside_tool_calls"));
838	        // Nothing of the rejected record stuck: no hold was opened.
839	        assert!(p.incomplete().is_empty());
840	    }
841	
842	    #[test]
843	    fn an_array_with_no_call_or_in_choice_level_keys_is_conforming() {
844	        let v = Verdicts::new();
845	        let mut p = OpenAiStream::default();
846	        assert!(p.step(rec(&chunk(json!([{"index":0,"delta":{"role":"assistant","content":"","foo":[{"index":0}]}}]))), &v).is_ok());
847	        assert!(p.step(rec(&chunk(json!([{"index":0,"delta":{"foo":[1]}}]))), &v).is_ok());
848	        start_call(&mut p, &v);
849	        // `tool_calls` itself, an empty one, and choice-level `logprobs` arrays are not merged as a delta.
850	        assert!(p.step(rec(&chunk(json!([{"index":0,"delta":{"tool_calls":[]},"logprobs":{"content":[{"token":"x"}]}}]))), &v).is_ok());
851	        assert!(p.step(rec(&args_frag("}")), &v).is_ok());
852	        assert!(p.step(rec(&finish_rec()), &v).is_ok());
853	        assert!(p.step(rec(&chunk(json!([{"index":0,"delta":{"foo":[1]}}]))), &v).is_ok(), "after the finish");
854	    }
