861	        p.step(rec(&chunk(json!([{"index":0,"delta":{"role":"assistant","content":""}}]))), &v).ok().unwrap();
862	        let frag = json!({"tool_calls":[{"index":0,"id":"c","type":"function","function":{"name":"read","arguments":"{"}}]});
863	        assert_eq!(dev(p.step(rec(&chunk(json!([{"index":0,"delta":frag},{"index":1}]))), &v)), Some("choice_without_delta"));
864	        assert!(p.incomplete().is_empty(), "no hold was opened");
865	    }
866	
867	    /// The `!finished` guard: after the finish no call is open, so both shapes are conforming.
868	    #[test]
869	    fn no_choices_or_no_delta_after_the_finish_is_conforming() {
870	        let v = Verdicts::new();
871	        let mut p = OpenAiStream::default();
872	        start_call(&mut p, &v);
873	        p.step(rec(&args_frag("}")), &v).ok().unwrap();
874	        p.step(rec(&finish_rec()), &v).ok().unwrap();
875	        assert!(p.step(rec(r#"{"object":"chat.completion.chunk","id":"c"}"#), &v).is_ok());
876	        assert!(p.step(rec(&chunk(json!([{"index":0}]))), &v).is_ok());
877	    }
878	
879	    /// Spec § 5.2: `"delta": null` stays `Malformed("delta")` in every position (SMA-749 classifier).
880	    #[test]
881	    fn a_null_delta_inside_an_open_call_is_a_stream_failure() {
882	        let mut p = OpenAiStream::default();
883	        let v = Verdicts::new();
884	        start_call(&mut p, &v);
885	        let r = p.step(rec(&chunk(json!([{"index":0,"delta":null}]))), &v);
886	        assert!(matches!(r, Err(StepError::Malformed)));
887	        // Through the interceptor, the non-empty queue makes it a stream failure under block.
888	        let chunks = vec![
889	            format!(
890	                "data: {}\n\n",
891	                chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"id":"c","type":"function","function":{"name":"read","arguments":"\"X1\""}}]}}]))
892	            ),
