1	// SPDX-License-Identifier: Apache-2.0
2	#![cfg_attr(not(test), allow(dead_code))]
3	//! Responses item assembly under the canonical rules (spec § 5, § 6.2, § 6.4, § 15).
4	//!
5	//! The decided value of a client-run item is always its `output_item.done` item (§ 5). The rules
6	//! make every other view a client SDK reads agree with it: the `added` item (the subset rule, A2),
7	//! the deltas and `*.done` events (R11–R14), and the item at the same index in the terminal
8	//! `output` (R9, R10). A stream that breaks a rule is a [`Deviation`], named after § 6.4.
9	//!
10	//! R5 lets one item be open at a time, so [`Assembly`] is one item-at-a-time state machine. Per
11	//! response it keeps the item ids and call ids (R8), the identity fields of every item (R9), and a
12	//! hash of every client-run `done` item (R10).
13	//!
14	//! Deltas are never retained. Each delta stream keeps a running SHA-256 hash, which is compared
15	//! with the hash of the `*.done` text and of the `done` item's text. So only the open item's
16	//! `added` item and the completed calls hold bytes ([`Assembly::retained`]). When the calls hold
17	//! more than the cap, they are dropped and the hold is never decided (749 D13, as an observed
18	//! hold): see [`Assembly::overflowed`]. Every rule is still checked after that point.
19	//!
20	//! The order of the checks on one event is: R1, R7, then the rules of the event's scope. After a
21	//! deviation, every later call to [`Assembly::accept`] returns the same deviation.
22	
23	use std::collections::HashSet;
24	
25	use serde_json::{Map, Value};
26	use sha2::{Digest, Sha256};
27	
28	use crate::json::{Malformed, check_numbers, opt_str, parse_value_strict};
29	use crate::protocol::{Deviation, MAX_IDENTIFIER_BYTES, raw_len};
30	use crate::report::{ReportDecision, ReportEntry};
31	use crate::responses::classify::{ItemClass, Scope, content_part_item, item_class, scope_of};
32	use crate::types::{ToolCall, ToolCallKind};
33	
34	/// The fields that R9 compares in `added`, `done` and the terminal `output`.
35	const IDENTITY: [&str; 5] = ["type", "id", "call_id", "namespace", "name"];
36	
37	/// The client-run item types whose model in the openai-python 3.48.0 output union
38	/// (`ResponseOutputItem`, `openai/types/responses/response_output_item.py`) has a `status` field.
39	/// For these an absent `status` at `done` is a truncation (R15, ruling T4b). The models of
40	/// `custom_tool_call`, `mcp_approval_request` and `mcp_approval_response` have no `status` field,
41	/// and a type that the union does not have has no model. `custom_tool_call_output` is
42	/// `ResponseCustomToolCallOutputItem` in the union, which declares `status`; the input model
43	/// `ResponseCustomToolCallOutput` does not.
44	const STATUS_TYPES: [&str; 8] = [
45	    "function_call",
46	    "function_call_output",
47	    "computer_call",
48	    "tool_search_call",
49	    "local_shell_call",
50	    "shell_call",
51	    "apply_patch_call",
52	    "custom_tool_call_output",
53	];
54	
55	/// The prefix of the gateway's own rewrite ids (§ 6.5). No upstream item id may start with it.
56	pub(crate) const RESERVED_ID_PREFIX: &str = "msg_paigasus_";
57	
58	type Hash = [u8; 32];
59	
60	fn finish(h: &Sha256) -> Hash {
61	    let mut out = [0; 32];
62	    out.copy_from_slice(&h.clone().finalize());
63	    out
64	}
65	
66	fn hash_str(s: &str) -> Hash {
67	    let mut h = Sha256::new();
68	    h.update(s.as_bytes());
69	    finish(&h)
70	}
71	
72	fn feed_str(h: &mut Sha256, s: &str) {
73	    h.update((s.len() as u64).to_be_bytes());
74	    h.update(s.as_bytes());
75	}
76	
77	/// Feed a JSON value so that two values hash equal exactly when they are equal as JSON values
78	/// (`Value::eq`): object keys in sorted order, so key order is no difference.
79	fn feed_value(h: &mut Sha256, v: &Value) {
80	    match v {
81	        Value::Null => h.update([0]),
82	        Value::Bool(b) => h.update([1, u8::from(*b)]),
83	        Value::Number(n) => {
84	            h.update([2]);
85	            // `-0.0 == 0.0` as a `Value`, but the two print differently.
86	            let text = if n.is_f64() && n.as_f64() == Some(0.0) { "0.0".to_owned() } else { n.to_string() };
87	            feed_str(h, &text);
88	        }
89	        Value::String(s) => {
90	            h.update([3]);
91	            feed_str(h, s);
92	        }
93	        Value::Array(a) => {
94	            h.update([4]);
95	            h.update((a.len() as u64).to_be_bytes());
96	            a.iter().for_each(|x| feed_value(h, x));
97	        }
98	        Value::Object(o) => {
99	            h.update([5]);
100	            h.update((o.len() as u64).to_be_bytes());
101	            let mut keys: Vec<&String> = o.keys().collect();
102	            keys.sort();
103	            for k in keys {
104	                feed_str(h, k);
105	                feed_value(h, &o[k.as_str()]);
106	            }
107	        }
108	    }
109	}
110	
111	fn hash_value(v: &Value) -> Hash {
112	    let mut h = Sha256::new();
113	    feed_value(&mut h, v);
114	    finish(&h)
115	}
116	
117	/// The fixed name of a built-in client-run kind (§ 5).
118	fn fixed_name(kind: ToolCallKind) -> Option<&'static str> {
119	    match kind {
120	        ToolCallKind::Computer => Some("computer"),
121	        ToolCallKind::LocalShell => Some("local_shell"),
122	        ToolCallKind::Shell => Some("shell"),
123	        ToolCallKind::ApplyPatch => Some("apply_patch"),
124	        ToolCallKind::ToolSearch => Some("tool_search"),
125	        _ => None,
126	    }
127	}
128	
129	fn text_of(item: &Map<String, Value>, key: &'static str) -> Result<String, Malformed> {
130	    match item.get(key) {
131	        Some(Value::String(s)) => Ok(s.clone()),
132	        _ => Err(Malformed(key)),
133	    }
134	}
135	
136	/// `(namespace, name)` of a client-run item (§ 5).
137	fn name_of(item: &Map<String, Value>, kind: ToolCallKind) -> Result<(Option<String>, String), Malformed> {
138	    if let Some(name) = fixed_name(kind) {
139	        return Ok((None, name.to_owned()));
140	    }
141	    Ok(match kind {
142	        ToolCallKind::Function => (opt_str(item.get("namespace"), "namespace")?, text_of(item, "name")?),
143	        ToolCallKind::Custom => (opt_str(item.get("namespace"), "namespace")?, text_of(item, "name")?),
144	        ToolCallKind::McpApprovalRequest => (opt_str(item.get("server_label"), "server_label")?, text_of(item, "name")?),
145	        ToolCallKind::Other => (None, text_of(item, "type")?),
146	        _ => return Err(Malformed("kind")),
147	    })
148	}
149	
150	/// The call of one client-run Responses item, by the § 5 table. Shared by the stream (the `done`
151	/// item) and the body path (an `output[]` item).
152	///
153	/// `namespace` is the `namespace` of a function or custom call (when present) and the
154	/// `server_label` of an `mcp_approval_request` (§ 5, ruling T4a).
155	/// `id` is the `call_id`, or the item `id` for `mcp_approval_request`. A server `tool_search_call`
156	/// may have no `call_id`. Kind `Other` takes the `call_id` when the item has one, else the item
157	/// `id` (§ 5 gives no row for it). `arguments` is `arguments` for a function (`""` becomes `"{}"`),
158	/// `input` for a custom call, and for every other kind the item as compact JSON in its own key
159	/// order, with `status` removed. The item's numbers must be exact (`check_numbers`, § 7.1).
160	pub(crate) fn tool_call(position: u32, item: &Map<String, Value>, kind: ToolCallKind) -> Result<ToolCall, Malformed> {
161	    item.values().try_for_each(check_numbers)?;
162	    let (namespace, name) = name_of(item, kind)?;
163	    let id = match kind {
164	        ToolCallKind::McpApprovalRequest => Some(text_of(item, "id")?),
165	        ToolCallKind::ToolSearch => opt_str(item.get("call_id"), "call_id")?,
166	        ToolCallKind::Other => match opt_str(item.get("call_id"), "call_id")? {
167	            Some(c) => Some(c),
168	            None => opt_str(item.get("id"), "id")?,
169	        },
170	        _ => Some(text_of(item, "call_id")?),
171	    };
172	    let arguments = match kind {
173	        ToolCallKind::Function => {
174	            let a = text_of(item, "arguments")?;
175	            if a.is_empty() { "{}".to_owned() } else { a }
176	        }
177	        ToolCallKind::Custom => text_of(item, "input")?,
178	        _ => {
179	            let stripped: Map<String, Value> = item.iter().filter(|(k, _)| *k != "status").map(|(k, v)| (k.clone(), v.clone())).collect();
180	            serde_json::to_string(&Value::Object(stripped)).expect("a Value always serializes")
181	        }
182	    };
183	    Ok(ToolCall {
184	        choice: 0,
185	        position,
186	        id,
187	        name,
188	        namespace,
189	        kind,
190	        arguments,
191	    })
192	}
