232	/// A delta stream: the running hash of the deltas and the hash of its `*.done` text.
233	#[derive(Default)]
234	struct Text {
235	    deltas: Sha256,
236	    done: Option<Hash>,
237	    /// Any delta or `*.done` event arrived.
238	    touched: bool,
239	    /// A delta after the `*.done` event, a second `*.done` event, or a value that is no string.
240	    broken: bool,
241	}
242	
243	impl Text {
244	    fn delta(&mut self, d: Option<&Value>) -> bool {
245	        self.touched = true;
246	        match d {
247	            Some(Value::String(s)) if self.done.is_none() => self.deltas.update(s.as_bytes()),
248	            _ => self.broken = true,
249	        }
250	        !self.broken
251	    }
252	
253	    /// Record the `*.done` text. `false` when the stream is broken or the text is not the deltas.
254	    fn done(&mut self, t: Option<&Value>) -> bool {
255	        self.touched = true;
256	        match t {
257	            Some(Value::String(s)) if self.done.is_none() => self.done = Some(hash_str(s)),
258	            _ => self.broken = true,
259	        }
260	        !self.broken && self.done == Some(finish(&self.deltas))
261	    }
262	
263	    /// The deltas, and the `*.done` text when one arrived, both equal `value`.
264	    fn agrees(&self, value: &str) -> bool {
265	        let h = hash_str(value);
266	        !self.broken && finish(&self.deltas) == h && self.done.is_none_or(|d| d == h)
267	    }
268	}
