300	/// R8: an object with a string `type` and a non-empty string `id`. The identity fields and
301	/// `server_label` are strings or `null` where present, and none is longer than
302	/// `MAX_IDENTIFIER_BYTES`.
303	pub(crate) fn item_shape(v: Option<&Value>) -> Result<(&Map<String, Value>, &str, &str), Deviation> {
304	    let bad = Deviation("item_shape");
305	    let Some(Value::Object(m)) = v else { return Err(bad) };
306	    let Some(Value::String(ty)) = m.get("type") else { return Err(bad) };
307	    let Some(Value::String(id)) = m.get("id") else { return Err(bad) };
308	    if id.is_empty() {
309	        return Err(bad);
310	    }
311	    let named = IDENTITY.iter().chain(&["server_label"]).filter_map(|k| m.get(*k));
312	    let mut long = false;
313	    for v in named {
314	        match v {
315	            Value::Null => {}
316	            Value::String(s) => long |= s.len() > MAX_IDENTIFIER_BYTES,
317	            _ => return Err(bad),
318	        }
319	    }
320	    if long {
321	        return Err(Deviation("long_identifier"));
322	    }
323	    Ok((m, ty, id))
324	}
