326	/// The subset rule (§ 6.4, A2): every field of `added`, at any depth, except the top-level
327	/// `status`, is `null`, `""`, `[]` or equal to the same field of `done`, and `done` has every
328	/// field that `added` has. An object field follows the rule inside; an array is `[]` or equal.
329	fn subset(added: &Map<String, Value>, done: &Map<String, Value>, top: bool) -> bool {
330	    added.iter().all(|(k, a)| {
331	        if top && k == "status" {
332	            return true;
333	        }
334	        let Some(d) = done.get(k) else { return false };
335	        match a {
336	            Value::Null => true,
337	            Value::String(s) if s.is_empty() => true,
338	            Value::Array(x) if x.is_empty() => true,
339	            Value::Object(ao) => matches!(d, Value::Object(dobj) if subset(ao, dobj, false)),
340	            _ => a == d,
341	        }
342	    })
343	}
