349	/// `action.commands` of a `shell_call` item: `None` when absent or `null`.
350	fn shell_commands(item: &Map<String, Value>) -> Result<Option<&Vec<Value>>, Deviation> {
351	    let bad = Deviation("shell_command_mismatch");
352	    match item.get("action") {
353	        None | Some(Value::Null) => Ok(None),
354	        Some(Value::Object(a)) => match a.get("commands") {
355	            None | Some(Value::Null) => Ok(None),
356	            Some(Value::Array(c)) => Ok(Some(c)),
357	            Some(_) => Err(bad),
358	        },
359	        Some(_) => Err(bad),
360	    }
361	}
