363	/// R13 per command event. Indexes appear in order, and a command ends before the next starts.
364	fn shell_event(commands: &mut Vec<Command>, ty: &str, ev: &Map<String, Value>) -> Result<(), Deviation> {
365	    let bad = Deviation("shell_command_mismatch");
366	    let i = index_of(ev.get("command_index")).ok_or(bad)? as usize;
367	    let text = |k: &str| match ev.get(k) {
368	        Some(Value::String(s)) => Ok(s.as_str()),
369	        _ => Err(bad),
370	    };
371	    if ty == "response.shell_call_command.added" {
372	        if i != commands.len() || commands.last().is_some_and(|c| c.done.is_none()) {
373	            return Err(bad);
374	        }
375	        let mut h = Sha256::new();
376	        h.update(text("command")?.as_bytes());
377	        commands.push(Command { text: h, done: None });
378	        return Ok(());
379	    }
380	    if i + 1 != commands.len() {
381	        return Err(bad);
382	    }
383	    let c = commands.last_mut().filter(|c| c.done.is_none()).ok_or(bad)?;
384	    if ty == "response.shell_call_command.delta" {
385	        c.text.update(text("delta")?.as_bytes());
386	    } else {
387	        let h = hash_str(text("command")?);
388	        if finish(&c.text) != h {
389	            return Err(bad);
390	        }
391	        c.done = Some(h);
392	    }
393	    Ok(())
394	}
