412	/// The per-kind rules of a client-run `done` item (R11–R14).
413	fn check_client(kind: ToolCallKind, open: &Open, added: &Map<String, Value>, done: &Map<String, Value>, completed: bool) -> Result<(), Deviation> {
414	    match kind {
415	        ToolCallKind::Function | ToolCallKind::Custom => {
416	            // R15 takes precedence over R11 (A3), and R12 is the same rule with `input`.
417	            if !completed {
418	                return Ok(());
419	            }
420	            let function = kind == ToolCallKind::Function;
421	            let (key, mismatch, added_label) = if function {
422	                ("arguments", "arguments_mismatch", "added_arguments")
423	            } else {
424	                ("input", "input_mismatch", "input_mismatch")
425	            };
426	            if !matches!(added.get(key), Some(Value::String(s)) if s.is_empty()) {
427	                return Err(Deviation(added_label));
428	            }
429	            let Some(Value::String(text)) = done.get(key) else { return Err(Deviation(mismatch)) };
430	            if !open.text.agrees(text) {
431	                return Err(Deviation(mismatch));
432	            }
433	            if function && !arguments_complete(text) {
434	                return Err(Deviation("incomplete_arguments"));
435	            }
436	        }
437	        ToolCallKind::Shell => {
438	            let bad = Deviation("shell_command_mismatch");
439	            let done_commands = shell_commands(done)?.map_or(&[][..], Vec::as_slice);
440	            // Ruling F2: `added` commands are `[]` or the `done` commands.
441	            if let Some(a) = shell_commands(added)?
442	                && !a.is_empty()
443	                && a.as_slice() != done_commands
444	            {
445	                return Err(bad);
446	            }
447	            if open.commands.len() != done_commands.len() {
448	                return Err(bad);
449	            }
450	            for (c, d) in open.commands.iter().zip(done_commands) {
451	                let Value::String(d) = d else { return Err(bad) };
452	                if c.done != Some(hash_str(d)) {
453	                    return Err(bad);
454	                }
455	            }
456	        }
457	        ToolCallKind::ApplyPatch => {
458	            let diff = match done.get("operation") {
459	                Some(Value::Object(op)) => op.get("diff"),
460	                _ => None,
461	            };
462	            let ok = match diff {
463	                Some(Value::String(d)) => open.text.agrees(d),
464	                None | Some(Value::Null) => !open.text.touched,
465	                Some(_) => false,
466	            };
467	            if !ok {
468	                return Err(Deviation("diff_mismatch"));
469	            }
470	        }
471	        _ => {}
472	    }
473	    Ok(())
474	}
