479	    failed: Option<Deviation>,
480	    started: bool,
481	    ended: bool,
482	    response_id: Option<String>,
483	    /// R7: whether events carry `sequence_number`, fixed by the first non-exempt event.
484	    numbered: Option<bool>,
485	    last_number: Option<u64>,
486	    items: Vec<Seen>,
487	    open: Option<Open>,
488	    ids: HashSet<String>,
489	    call_ids: HashSet<String>,
490	    /// The `output_index` of every client-run item, in order: a call's slot is its place here.
491	    client: Vec<u32>,
492	    /// `(output_index, display_name)` of every client-run item so far.
493	    names: Vec<(u32, String)>,
494	    calls: Vec<ToolCall>,
495	    hold_open: bool,
496	    truncated: bool,
497	    overflowed: bool,
498	    /// The bytes of the open `added` item and of the calls' arguments.
