500	}
501	
502	impl Assembly {
503	    /// `cap` is the stream's `max_held_bytes`: the calls of a response that hold more are dropped.
504	    pub(crate) fn with_cap(cap: usize) -> Self {
505	        Assembly {
506	            cap,
507	            failed: None,
508	            started: false,
509	            ended: false,
510	            response_id: None,
511	            numbered: None,
512	            last_number: None,
513	            items: Vec::new(),
514	            open: None,
515	            ids: HashSet::new(),
516	            call_ids: HashSet::new(),
517	            client: Vec::new(),
518	            names: Vec::new(),
519	            calls: Vec::new(),
520	            hold_open: false,
521	            truncated: false,
522	            overflowed: false,
523	            held: 0,
524	        }
525	    }
526	
527	    /// Apply one classified event (`ty` is its `data.type`). `keepalive` and `error` are exempt
528	    /// (§ 6.4). A record after the terminal event changes nothing: the stream drops and counts it
529	    /// (R3, ruling F8).
530	    pub(crate) fn accept(&mut self, ty: &'static str, v: &Value) -> Result<Effect, Deviation> {
531	        if let Some(d) = self.failed {
532	            return Err(d);
533	        }
534	        let r = self.step(ty, v);
535	        if let Err(d) = r {
536	            self.failed = Some(d);
537	        }
538	        r
539	    }
540	
541	    fn step(&mut self, ty: &'static str, v: &Value) -> Result<Effect, Deviation> {
542	        let scope = scope_of(ty);
543	        if matches!(scope, Scope::Keepalive | Scope::Error) || self.ended {
544	            return Ok(Effect::other());
545	        }
546	        let Value::Object(ev) = v else { return Err(Deviation("not_object")) };
547	        if !self.started && ty != "response.created" {
548	            return Err(Deviation("first_not_created"));
549	        }
550	        if self.started && ty == "response.created" {
551	            return Err(Deviation("repeated_created"));
552	        }
553	        self.sequence(ev)?;
554	        match scope {
555	            Scope::Lifecycle => {
556	                let resp = self.response_of(ev, ty == "response.created")?;
557	                if !matches!(resp.get("output"), Some(Value::Array(a)) if a.is_empty()) {
558	                    return Err(Deviation("early_output"));
559	                }
560	                self.started = true;
561	                Ok(Effect::other())
562	            }
563	            Scope::Terminal => self.terminal(ev),
564	            Scope::ItemAdded => self.added(ev),
565	            Scope::ItemDone => self.done(ev),
566	            Scope::Item(item_type) => self.middle(ty, item_type, v, ev),
567	            Scope::ResponseLevel | Scope::Keepalive | Scope::Error => Ok(Effect::other()),
568	        }
569	    }
570	
571	    /// R7: an integer that strictly increases, on every event or on none.
572	    fn sequence(&mut self, ev: &Map<String, Value>) -> Result<(), Deviation> {
573	        let bad = Deviation("sequence_number");
574	        let n = match ev.get("sequence_number") {
575	            None => None,
576	            Some(Value::Number(n)) if n.is_u64() => n.as_u64(),
577	            Some(_) => return Err(bad),
578	        };
579	        match (*self.numbered.get_or_insert(n.is_some()), n) {
580	            (true, Some(n)) if self.last_number.is_none_or(|l| n > l) => {
581	                self.last_number = Some(n);
582	                Ok(())
583	            }
584	            (false, None) => Ok(()),
585	            _ => Err(bad),
586	        }
587	    }
588	
589	    /// R1: the `response` object, whose `id` is the same on every lifecycle and terminal event.
590	    fn response_of<'a>(&mut self, ev: &'a Map<String, Value>, created: bool) -> Result<&'a Map<String, Value>, Deviation> {
591	        let bad = Deviation(if created && self.response_id.is_none() { "first_not_created" } else { "response_id_changed" });
592	        let Some(Value::Object(resp)) = ev.get("response") else { return Err(bad) };
593	        let Some(Value::String(id)) = resp.get("id") else { return Err(bad) };
594	        match &self.response_id {
595	            None => self.response_id = Some(id.clone()),
596	            Some(prev) if prev == id => {}
597	            Some(_) => return Err(Deviation("response_id_changed")),
598	        }
599	        Ok(resp)
600	    }
601	
602	    /// R3, R9, R10, and R15 for a client-run item with no `done`.
603	    fn terminal(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
604	        let resp = self.response_of(ev, false)?;
605	        let Some(Value::Array(output)) = resp.get("output") else {
606	            return Err(Deviation("terminal_output_missing"));
607	        };
608	        let mismatch = Deviation("terminal_output_mismatch");
609	        if output.len() != self.items.len() {
610	            return Err(mismatch);
611	        }
612	        for (seen, v) in self.items.iter().zip(output) {
613	            let Value::Object(item) = v else { return Err(mismatch) };
614	            if identity(item) != seen.identity {
615	                return Err(Deviation("item_identity_changed"));
616	            }
617	            if seen.done_hash.is_some_and(|h| h != hash_value(v)) {
618	                return Err(mismatch);
619	            }
620	        }
621	        if let Some(open) = self.open.take() {
622	            if matches!(open.class, ItemClass::ClientRun(_)) {
623	                self.truncated = true;
624	            }
625	            self.held -= open.added.as_ref().map_or(0, raw_len);
626	        }
627	        self.ended = true;
628	        Ok(Effect { terminal: true, ..Effect::other() })
629	    }
630	
631	    /// R4, R5, R8 at `response.output_item.added`.
632	    fn added(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
633	        let value = ev.get("item");
634	        let (item, ty, id) = item_shape(value)?;
635	        let next = u32::try_from(self.items.len()).unwrap_or(u32::MAX);
636	        let index = index_of(ev.get("output_index")).ok_or(Deviation("index_order"))?;
637	        if index < next {
638	            return Err(Deviation("index_reused"));
639	        }
640	        if index > next {
641	            return Err(Deviation("index_order"));
642	        }
643	        if self.open.is_some() {
644	            return Err(Deviation("item_interleaved"));
645	        }
646	        if id.starts_with(RESERVED_ID_PREFIX) {
647	            return Err(Deviation("reserved_id"));
648	        }
649	        if self.ids.contains(id) {
650	            return Err(Deviation("duplicate_id"));
651	        }
652	        let call_id = match item.get("call_id") {
653	            Some(Value::String(c)) => Some(c),
654	            _ => None,
655	        };
656	        if call_id.is_some_and(|c| self.call_ids.contains(c)) {
657	            return Err(Deviation("duplicate_call_id"));
658	        }
659	        self.ids.insert(id.to_owned());
660	        if let Some(c) = call_id {
661	            self.call_ids.insert(c.clone());
662	        }
663	        let class = item_class(ty);
664	        let mut effect = Effect {
665	            frame: ItemFrame::Added,
666	            ..Effect::other()
667	        };
668	        let mut added = None;
669	        match class {
670	            ItemClass::ClientRun(kind) => {
671	                effect.item = Some(index);
672	                if !self.hold_open {
673	                    self.hold_open = true;
674	                    effect.opened = true;
675	                }
676	                self.client.push(index);
677	                // The name the calls not assembled yet are known by (a `BlockAll` report).
678	                let name = match name_of(item, kind) {
679	                    Ok((Some(ns), name)) => format!("{ns}.{name}"),
680	                    Ok((None, name)) => name,
681	                    Err(_) => kind.as_str().to_owned(),
682	                };
683	                self.names.push((index, name));
684	                let v = value.cloned().expect("item_shape found the item");
685	                self.held += raw_len(&v);
686	                added = Some(v);
687	            }
688	            ItemClass::ProviderRun => {
689	                effect.report = Some(ReportEntry {
690	                    choice: 0,
691	                    position: index,
692	                    name: ty.to_owned(),
693	                    decision: ReportDecision::Unenforceable,
694	                    basis: None,
695	                    code: None,
696	                });
697	            }
698	            ItemClass::Content => {}
699	        }
700	        self.items.push(Seen {
701	            identity: identity(item),
702	            done: false,
703	            done_hash: None,
704	        });
705	        self.open = Some(Open {
706	            index,
707	            ty: ty.to_owned(),
708	            id: id.to_owned(),
709	            class,
710	            added,
711	            text: Text::default(),
712	            commands: Vec::new(),
713	        });
714	        Ok(effect)
715	    }
716	
717	    /// R6 and R16: the event's `output_index` is the open item's.
718	    fn locate(&self, ev: &Map<String, Value>) -> Result<u32, Deviation> {
719	        let index = index_of(ev.get("output_index")).ok_or(Deviation("wrong_item_index"))?;
720	        if self.open.as_ref().is_some_and(|o| o.index == index) {
721	            return Ok(index);
722	        }
723	        if self.items.get(index as usize).is_some_and(|s| s.done) {
724	            return Err(Deviation("event_after_done"));
725	        }
726	        Err(Deviation("wrong_item_index"))
727	    }
728	
729	    /// An item-scoped event between `added` and `done` (R6, R11–R14 ordering, R16).
730	    fn middle(&mut self, ty: &'static str, item_type: &'static str, v: &Value, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
731	        let index = self.locate(ev)?;
732	        let open = self.open.as_mut().expect("locate found the open item");
733	        // Ruling T3a: a content part belongs to the item type its part names.
734	        let expected = if ty.starts_with("response.content_part.") {
735	            content_part_item(v).map_err(|_| Deviation("event_item_type"))?
736	        } else {
737	            item_type
738	        };
739	        if open.ty != expected {
740	            return Err(Deviation("event_item_type"));
741	        }
742	        // `response.shell_call_command.*` is the one item-scoped family with no `item_id`.
743	        let no_item_id = ty.starts_with("response.shell_call_command.");
744	        match ev.get("item_id") {
745	            Some(Value::String(s)) if *s == open.id => {}
746	            None if no_item_id => {}
747	            _ => return Err(Deviation("item_id_mismatch")),
748	        }
749	        // Function and custom streams are judged at `done`, where R15 can take precedence (A3).
750	        // An apply-patch diff and a shell command are judged here too.
751	        let diff_ok = match ty {
752	            "response.function_call_arguments.delta" | "response.custom_tool_call_input.delta" => {
753	                open.text.delta(ev.get("delta"));
754	                true
755	            }
756	            "response.function_call_arguments.done" => {
757	                open.text.done(ev.get("arguments"));
758	                true
759	            }
760	            "response.custom_tool_call_input.done" => {
761	                open.text.done(ev.get("input"));
762	                true
763	            }
764	            "response.apply_patch_call_operation_diff.delta" => open.text.delta(ev.get("delta")),
765	            "response.apply_patch_call_operation_diff.done" => open.text.done(ev.get("diff")),
766	            _ if no_item_id => {
767	                shell_event(&mut open.commands, ty, ev)?;
768	                true
769	            }
770	            _ => true,
771	        };
772	        if !diff_ok {
773	            return Err(Deviation("diff_mismatch"));
774	        }
775	        let client = matches!(open.class, ItemClass::ClientRun(_));
776	        Ok(Effect {
777	            frame: ItemFrame::Middle,
778	            item: client.then_some(index),
779	            ..Effect::other()
780	        })
781	    }
782	
783	    /// R9, R11–R15 and the subset rule at `response.output_item.done`.
784	    fn done(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
785	        let value = ev.get("item");
786	        let (item, item_type, _) = item_shape(value)?;
787	        let index = self.locate(ev)?;
788	        if identity(item) != self.items[index as usize].identity {
789	            return Err(Deviation("item_identity_changed"));
790	        }
791	        let open = self.open.take().expect("locate found the open item");
792	        let mut client = false;
793	        if let ItemClass::ClientRun(kind) = open.class {
794	            client = true;
795	            let added_value = open.added.as_ref().expect("a client-run item keeps its added item");
796	            let added = added_value.as_object().expect("item_shape checked the added item");
797	            // R15: a `done` whose `status` is not `"completed"` is a truncation. An absent `status`
798	            // is one too, except for an item type whose model has no `status` field (T4b).
799	            let completed = is_completed(item, item_type);
800	            check_client(kind, &open, added, item, completed)?;
801	            if !subset(added, item, true) {
802	                return Err(Deviation("added_done_differ"));
803	            }
804	            let call = tool_call(index, item, kind).map_err(|m| Deviation(if m.0 == "lossy_number" { "lossy_number" } else { "item_shape" }))?;
805	            if !completed {
806	                self.truncated = true;
807	            }
808	            self.held -= raw_len(added_value);
809	            if let Some(n) = self.names.last_mut() {
810	                *n = (index, call.display_name());
811	            }
812	            if !self.overflowed {
813	                self.held += call.arguments.len();
814	                self.calls.push(call);
815	                if self.held > self.cap {
816	                    // 749 D13: an outgrown hold keeps nothing and is never decided.
817	                    self.overflowed = true;
818	                    self.held -= std::mem::take(&mut self.calls).iter().map(|c| c.arguments.len()).sum::<usize>();
819	                }
820	            }
821	            self.items[index as usize].done_hash = value.map(hash_value);
822	        }
823	        self.items[index as usize].done = true;
824	        Ok(Effect {
825	            frame: ItemFrame::Done,
826	            item: client.then_some(index),
827	            ..Effect::other()
828	        })
829	    }
830	
831	    /// Whether the response hold opened: a client-run item was added (D10). It stays `true`.
832	    pub(crate) fn hold_open(&self) -> bool {
833	        self.hold_open
834	    }
835	
836	    /// R15: a client-run `done` was not `"completed"`, or the terminal event arrived while a
837	    /// client-run item had no `done`. (`[DONE]` and EOF before the terminal are the stream's.)
838	    pub(crate) fn truncated(&self) -> bool {
839	        self.truncated
840	    }
841	
842	    /// The calls outgrew the cap and were dropped: the hold must never be decided as allowed on
843	    /// the strength of [`Assembly::hold_calls`], which is then empty (749 D13).
844	    pub(crate) fn overflowed(&self) -> bool {
845	        self.overflowed
846	    }
847	
848	    /// The completed calls, in `output_index` order. Moves them out. Empty after an overflow.
849	    pub(crate) fn hold_calls(&mut self) -> Vec<ToolCall> {
850	        let calls = std::mem::take(&mut self.calls);
851	        self.held -= calls.iter().map(|c| c.arguments.len()).sum::<usize>();
852	        calls
853	    }
854	
855	    /// The slot (place in the hold's call order) of the client-run item at `output_index`.
856	    pub(crate) fn slot_of(&self, output_index: u32) -> Option<usize> {
857	        self.client.iter().position(|i| *i == output_index)
858	    }
859	
860	    /// `(output_index, display_name)` of every client-run item so far, done or not.
861	    pub(crate) fn known(&self) -> Vec<(u32, String)> {
862	        self.names.clone()
863	    }
864	
865	    /// R7: the stream's events carry `sequence_number`.
866	    pub(crate) fn sequence_numbers(&self) -> bool {
867	        self.numbered == Some(true)
868	    }
869	
870	    /// The bytes held in the open `added` item and the calls' arguments, measured exactly.
871	    #[cfg(test)]
872	    pub(crate) fn retained(&self) -> usize {
873	        let added = self.open.as_ref().and_then(|o| o.added.as_ref()).map_or(0, raw_len);
874	        let held = added + self.calls.iter().map(|c| c.arguments.len()).sum::<usize>();
875	        assert_eq!(held, self.held, "the held-byte count is exact");
876	        held
877	    }
878	}
879	
