            self.bom = BomState::Done;
            if head.starts_with(BOM) {
                head.drain(..BOM.len());
            }
            for &b in &head {
                self.byte(b, &mut out);
            }
            return out;
        }
        for &b in chunk {
            self.byte(b, &mut out);
        }
        out
