    /// The § 4.6 schema. Every field is ASCII by construction.
    #[must_use]
    pub fn to_json(&self) -> String {
        serde_json::json!({
            "v": 1,
            "choice": self.choice,
            "position": self.position,
            "name": sanitize_name(&self.name),
            "name_sha256_8": name_sha256_8(&self.name),
            "decision": self.decision.as_str(),
