            }
            Some("custom") => {
                let c = opt_obj(t.get("custom"), "custom")?.ok_or(Malformed("custom"))?;
                f.definitions.push(ToolDefinition {
                    name: req_str(c, "name")?,
                    namespace: None,
                    kind: ToolCallKind::Custom,
                    schema: None,
